package com.sabz.companion;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.provider.Settings;import android.webkit.*;import android.view.*;import android.widget.*;import android.print.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.json.*;
public class MainActivity extends Activity {
 private WebView web,report;private FrameLayout root;private String pendingReview;private String pendingBackup;private boolean quickRequested=false;
 static final String BASE="https://appassets.androidplatform.net/assets/";
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xfff8f8f2);getWindow().setNavigationBarColor(0xffffffff);root=new FrameLayout(this);root.setBackgroundColor(0xfff8f8f2);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets pad=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(pad.left,pad.top,pad.right,pad.bottom);return insets;});web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);configureWeb(web);web.addJavascriptInterface(new Bridge(),"Android");web.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsConfirm(WebView v,String url,String message,JsResult result){dialogBuilder().setMessage(message).setPositiveButton(android.R.string.ok,(d,w)->result.confirm()).setNegativeButton(android.R.string.cancel,(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}@Override public boolean onJsAlert(WebView v,String u,String m,JsResult r){dialogBuilder().setMessage(m).setPositiveButton(android.R.string.ok,(d,w)->r.confirm()).show();return true;}});web.setWebViewClient(new AssetsClient(){@Override public void onPageFinished(WebView v,String u){if(pendingReview!=null){String date=pendingReview;pendingReview=null;web.evaluateJavascript("window.openReview("+JSONObject.quote(date)+")",null);}else if(quickRequested){quickRequested=false;web.evaluateJavascript("window.openQuick && window.openQuick()",null);}}});quickRequested=getIntent().getBooleanExtra("quick",false);pendingReview=getIntent().getStringExtra("reviewDate");web.loadUrl(BASE+"index.html");ReminderReceiver.createChannel(this);ReminderReceiver.schedule(this);}
 private void configureWeb(WebView v){WebView.setWebContentsDebuggingEnabled((getApplicationInfo().flags & android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0);WebSettings s=v.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportZoom(false);v.setWebViewClient(new AssetsClient());}
 class AssetsClient extends WebViewClient {@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest req){String u=req.getUrl().toString();if(u.startsWith(BASE)){String path=Uri.decode(u.substring(BASE.length()).split("\\?")[0]);if(path.contains("..")||path.startsWith("/"))return denied();try{String mime=path.endsWith(".css")?"text/css":path.endsWith(".js")?"application/javascript":path.endsWith(".ttf")?"font/ttf":path.endsWith(".svg")?"image/svg+xml":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open(path));}catch(IOException e){return denied();}}return denied();}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}private WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}
 @Override protected void onResume(){super.onResume();ReminderReceiver.schedule(this);}
 @Override public void onBackPressed(){web.evaluateJavascript("window.nativeBack()",null);}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(i.hasExtra("reviewDate"))web.evaluateJavascript("window.openReview("+JSONObject.quote(i.getStringExtra("reviewDate"))+")",null);else if(i.getBooleanExtra("quick",false))web.evaluateJavascript("window.openQuick && window.openQuick()",null);}
 private void error(){runOnUiThread(()->web.evaluateJavascript("window.onNativeError()",null));}
 private AlertDialog.Builder dialogBuilder(){return new AlertDialog.Builder(MainActivity.this,getSharedPreferences("prefs",MODE_PRIVATE).getBoolean("dark",false)?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert);}
 private boolean fa(){return getSharedPreferences("prefs",MODE_PRIVATE).getBoolean("fa",true);}
 public class Bridge {
  @JavascriptInterface public void setTheme(boolean dark){getSharedPreferences("prefs",MODE_PRIVATE).edit().putBoolean("dark",dark).apply();runOnUiThread(()->{int color=dark?0xff181a20:0xfff8f8f2;root.setBackgroundColor(color);web.setBackgroundColor(color);getWindow().setStatusBarColor(color);getWindow().setNavigationBarColor(color);WindowInsetsController control=getWindow().getInsetsController();if(control!=null){int light=WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS;control.setSystemBarsAppearance(dark?0:light,light);}});}
  @JavascriptInterface public void testNightReview(){runOnUiThread(()->{if(!getSystemService(NotificationManager.class).areNotificationsEnabled()){Toast.makeText(MainActivity.this,fa()?"ابتدا مجوز اعلان را فعال کن":"Enable notifications first",Toast.LENGTH_LONG).show();return;}ReminderReceiver.notifyReview(MainActivity.this,java.time.LocalDate.now().toString(),true);});}

  @JavascriptInterface public String load(){return getSharedPreferences("data",MODE_PRIVATE).getString("state","");}
  @JavascriptInterface public boolean save(String raw){if(raw.length()>5000000)return false;try{JSONObject o=new JSONObject(raw);if(o.getInt("version")!=1)return false;return getSharedPreferences("data",MODE_PRIVATE).edit().putString("state",raw).commit();}catch(Exception e){return false;}}
  @JavascriptInterface public void configure(String raw){try{JSONObject o=new JSONObject(raw);getSharedPreferences("prefs",MODE_PRIVATE).edit().putBoolean("enabled",o.optBoolean("reminders",false)).putBoolean("fa","fa".equals(o.optString("lang"))).putInt("wake",o.optInt("wake",8)).putInt("sleep",o.optInt("sleep",22)).commit();runOnUiThread(()->{if(o.optBoolean("reminders",false)&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)MainActivity.this.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},11);ReminderReceiver.schedule(MainActivity.this);});}catch(Exception e){error();}}
  @JavascriptInterface public String notificationStatus(){boolean allowed=getSystemService(NotificationManager.class).areNotificationsEnabled();boolean exact=Build.VERSION.SDK_INT<31||getSystemService(AlarmManager.class).canScheduleExactAlarms();return "{\"notifications\":"+allowed+",\"exact\":"+exact+"}";}
  @JavascriptInterface public void requestPermissions(){runOnUiThread(()->{try{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){MainActivity.this.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},12);}else if(Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager.class).canScheduleExactAlarms()){startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}else{Intent i=new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS);i.putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);}}catch(Exception e){error();}});}
  @JavascriptInterface public void testNotification(){runOnUiThread(()->{if(!getSystemService(NotificationManager.class).areNotificationsEnabled()){Toast.makeText(MainActivity.this,fa()?"ابتدا مجوز اعلان را فعال کن":"Enable notifications first",Toast.LENGTH_LONG).show();return;}ReminderReceiver.notifyUser(MainActivity.this,true,true);});}
  @JavascriptInterface public void minimize(){runOnUiThread(()->moveTaskToBack(true));}
  @JavascriptInterface public void openSource(String url){runOnUiThread(()->{try{Uri u=Uri.parse(url);String host=u.getHost();if(!"https".equals(u.getScheme())||host==null)return;if(!(host.equals("www.niddk.nih.gov")||host.equals("www.fda.gov")||host.equals("www.ncbi.nlm.nih.gov")||host.equals("www.who.int")||host.equals("fdc.nal.usda.gov")))return;startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){error();}});}
  @JavascriptInterface public void exportBackup(String raw){if(raw.length()>5000000)return;pendingBackup=raw;runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"sabz-backup-"+java.time.LocalDate.now()+".json");startActivityForResult(i,101);});}
  @JavascriptInterface public void importBackup(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,102);});}
  @JavascriptInterface public void printReport(String html){if(html.length()>2000000)return;runOnUiThread(()->{if(report!=null)report.destroy();report=new WebView(MainActivity.this);configureWeb(report);report.setWebViewClient(new AssetsClient(){@Override public void onPageFinished(WebView v,String u){v.evaluateJavascript("document.fonts.ready.then(()=>true)",s->new Handler(Looper.getMainLooper()).postDelayed(()->{try{PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("گزارش سیب سلامت",v.createPrintDocumentAdapter("گزارش سیب سلامت"),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setColorMode(PrintAttributes.COLOR_MODE_COLOR).build());}catch(Exception ex){error();}},500));}});report.loadDataWithBaseURL(BASE,html,"text/html","UTF-8",null);});}
 }
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);ReminderReceiver.schedule(this);if(r==12&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager.class).canScheduleExactAlarms()){startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;try{if(req==101&&pendingBackup!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pendingBackup.getBytes(StandardCharsets.UTF_8));}pendingBackup=null;Toast.makeText(this,fa()?"پشتیبان ذخیره شد":"Backup saved",Toast.LENGTH_SHORT).show();}if(req==102){String raw;try(InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int len,total=0;while((len=in.read(b))!=-1){total+=len;if(total>5000000)throw new IOException("Too large");out.write(b,0,len);}raw=out.toString("UTF-8");}web.evaluateJavascript("window.receiveBackup("+JSONObject.quote(raw)+")",null);}}catch(Exception e){error();}}
 @Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("Android");web.destroy();}if(report!=null)report.destroy();super.onDestroy();}
}
